head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setVisibleRowNum]<br/>GridView 컴포넌트의 visibleRowNum 속성을 설정합니다.",
    "validation" : [
        "rowNum(필수) 파라미터로 Body 영역에 한번에 표시할 Row 의 갯수를 숫자로 설정합니다. ''(Empty), 'all' 은 메소드로 설정할 수 없습니다.",
        "설정값과 데이터 수에 따라 GridView 의 높이가 재조정됩니다.",
        "rowNum 이 NaN, 음수, 유효하지 않으면 false 를 반환하며 메소드는 실행되지 않습니다.",
        "rowNum 이 유효한 양의 정수이면 실행 후 undefined 를 반환합니다.",
        "setVisibleRowNum() 실행 시 initFixedHeightByRowNum 속성도 rowNum 값으로 설정됩니다.",
        "getVisibleRowNum() 은 visibleRowNum 속성값을 반환하지 않습니다(관련은 있음).",
        "rowNum 에 실제 데이터 수보다 큰 값 설정 시 높이는 실제 데이터 수에 맞춰 재조정됩니다. 이후 데이터 수가 visibleRowNum 속성값보다 커지면 visibleRowNum 에 맞게 다시 조정됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성 (5 행 — rowNum 값에 따른 높이 차이가 보이도록 데이터 확보)
    await $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 5);

    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // 디자인 높이를 작게 설정 + 마지막 컬럼 width="*"(가로 스크롤 방지)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:500px;height:171px;">';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" inputType="text" id="hcol1" value="col1"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="hcol2" value="col2"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="hcol3" value="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col4"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" inputType="text" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col2" dataList="col2"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="col3" dataList="col3"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate('target1', 'gridView', strTarget, grp_comp);
}



// par_rowNum 값으로 setVisibleRowNum() 호출 → 반환값(즉시) + 높이/getVisibleRowNum(redraw 정착 후)
scwin.btn_setVisibleRowNum_onclick = function (e) {
    let rowNum = par_rowNum.getValue();

    // 반환값 (false=미실행 / undefined=실행) — 동기적으로 즉시 출력
    let ret = target1.setVisibleRowNum(rowNum);
    wf_body_bottom.getObj("scwin").setReturnValue("setVisibleRowNum('" + rowNum + "') 반환값 : " + ret);

    // 높이 재조정/getVisibleRowNum 은 redraw 정착 후 읽어야 정확함
    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("데이터 수 : " + target1.getDataLength() + " / 렌더 높이 : " + target1.render.offsetHeight + " / getVisibleRowNum() : " + target1.getVisibleRowNum());
        wf_body_bottom.getObj("scwin").setReturnValue("options.visibleRowNum : " + target1.options.visibleRowNum + " / options.initFixedHeightByRowNum : " + target1.options.initFixedHeightByRowNum);
    }, 500);
}



// 데이터 추가 — 바인딩된 DataList(dlt_bind)에 Row 를 추가하여 데이터 수를 늘림.
// 데이터 수 > visibleRowNum 이 되면 높이가 visibleRowNum 에 맞게 재조정되는지 관찰 (@spec3)
scwin.btn_insertRow_onclick = function (e) {
    // 한 번에 3 행씩 추가 (rowNum 10 으로 설정 후 데이터 수가 10 을 넘도록)
    dlt_bind.insertRow();
    dlt_bind.insertRow();
    dlt_bind.insertRow();

    // 높이 재조정은 redraw 정착 후 읽음
    setTimeout(function () {
        wf_body_bottom.getObj("scwin").setReturnValue("데이터 추가 후 데이터 수 : " + target1.getDataLength() + " / options.visibleRowNum : " + target1.options.visibleRowNum + " / 렌더 높이 : " + target1.render.offsetHeight);
    }, 500);
}
